mapper.select:
SELECT 
FROM inspection_task task

WHERE task.tenant_id = #{tenantId} AND task.id = #{id}
  AND task.deleted = 0
  AND (

    OR (#{scope.selfData} = 1 AND (
        task.assignee_user_id = #{scope.userId}
        OR EXISTS (
            SELECT 1 FROM inspection_task_assignee scoped_assignee
            WHERE scoped_assignee.tenant_id = task.tenant_id
              AND scoped_assignee.task_id = task.id
              AND scoped_assignee.user_id = #{scope.userId}
        )
    ))
  )
LIMIT 1

SELECT attachment_id FROM inspection_attachment
WHERE tenant_id = #{tenantId} AND task_result_id = #{taskResultId}
ORDER BY id

SELECT COUNT(*)
FROM inspection_attachment relation
JOIN system_attachment attachment
  ON attachment.tenant_id = relation.tenant_id
 AND attachment.id = relation.attachment_id
 AND attachment.deleted = 0
WHERE relation.tenant_id = #{tenantId}
  AND relation.task_id = #{taskId}
  AND relation.attachment_id = #{attachmentId}

mapper.update:
UPDATE inspection_task
SET task_status = #{targetStatus},
    cancel_reason = CASE WHEN #{targetStatus} = 'CANCELLED' THEN #{request.reason}
                         ELSE cancel_reason END,
    void_reason = CASE WHEN #{targetStatus} = 'VOIDED' THEN #{request.reason}
                       ELSE void_reason END,
    updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{id} AND deleted = 0
  AND version = #{request.version}
  AND task_status NOT IN ('COMPLETED','CANCELLED','VOIDED')
